const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const defs={weight:'Weight',waist:'Waist',hips:'Hips',chest:'Chest',thigh:'Thigh',arm:'Upper arm',neck:'Neck'};
const key='weight-n-waist-v1';let state={entries:[],units:'metric',extras:['hips','chest'],started:false};let storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Array.isArray(saved.entries))state={...state,...saved};}catch(e){storageOK=false;}
let demo=!state.started,metric='weight',page='overview';
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const samples=Array.from({length:12},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(11-i)*5);return {id:'sample-'+i,date:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,weight:[78.5,78.1,78.3,77.6,77.4,77.7,76.9,76.6,76.8,76.2,75.9,75.6][i],waist:[86,85.8,85.9,85.1,85,84.7,84.8,84.2,84,83.7,83.5,83.2][i],hips:99-i*.12,chest:96-i*.08,note:i===11?'A little more energy today':i===10?'Morning check-in':''};});
const rows=()=>[...(demo?samples:state.entries)].sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id));
const unit=m=>state.units==='imperial'?(m==='weight'?'lb':'in'):(m==='weight'?'kg':'cm');
const convert=(v,m)=>v==null?null:v*(state.units==='imperial'?(m==='weight'?2.2046226218:1/2.54):1);
const canonical=(v,m)=>v/(state.units==='imperial'?(m==='weight'?2.2046226218:1/2.54):1);
const num=(v,m)=>v==null?'—':convert(v,m).toFixed(1);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
function save(){try{localStorage.setItem(key,JSON.stringify(state));storageOK=true;return true;}catch(e){storageOK=false;toast('Storage unavailable. Export your history before closing.');return false;}}
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
function stat(m){const r=rows().filter(e=>Number.isFinite(e[m])),last=r.at(-1),first=r[0],delta=last?convert(last[m]-first[m],m):null;return `<article class="stat"><div class="stat-label">${defs[m]}</div><span class="stat-icon" aria-hidden="true">${m==='weight'?'◷':'↔'}</span><div class="stat-value">${num(last?.[m],m)} <small>${unit(m)}</small></div><div class="stat-sub">${r.length>1?`<span class="change">${delta>0?'+':''}${delta.toFixed(1)} ${unit(m)}</span> since first check-in`:last?'Your starting point':'Your first check-in awaits'}</div></article>`;}
function render(){ $('#sample-banner').hidden=!demo;$('.local').innerHTML=`<span>●</span> ${storageOK?'Saved on this device':'Storage unavailable'}`;$('#stats').innerHTML=stat('weight')+stat('waist')+`<article class="stat"><div class="stat-label">Showing up for yourself</div><span class="stat-icon" aria-hidden="true">✧</span><div class="stat-value">${rows().length}<small>check-ins</small></div><div class="stat-sub">${rows().length?`<span class="change">One step at a time</span> Since ${dateLabel(rows()[0].date)}`:'Start whenever you’re ready'}</div></article>`;$('#recent-list').innerHTML=table(rows().slice(-3).reverse(),false);$('#history-list').innerHTML=table(rows().reverse(),true);$('#body-stats').innerHTML=['waist',...state.extras].map(stat).join('');chart();}
function table(data,actions){if(!data.length)return '<div class="empty"><strong>Your story starts here.</strong>Log your first measurement to begin your journal.</div>';return `<div class="table-wrap"><table><thead><tr><th>Date</th><th>Weight</th><th>Waist</th>${actions?state.extras.map(m=>`<th>${defs[m]}</th>`).join(''):''}<th>Note</th>${actions?'<th>Actions</th>':''}</tr></thead><tbody>${data.map(e=>`<tr><td>${dateLabel(e.date)}</td><td>${num(e.weight,'weight')} <small>${unit('weight')}</small></td><td>${num(e.waist,'waist')} <small>${unit('waist')}</small></td>${actions?state.extras.map(m=>`<td>${num(e[m],m)} <small>${unit(m)}</small></td>`).join(''):''}<td class="notes-cell" title="${esc(e.note)}">${esc(e.note)||'—'}</td>${actions?`<td><button class="row-action" data-edit="${esc(e.id)}">Edit</button> <button class="row-action" data-delete="${esc(e.id)}">Delete</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function chart(){ $('#chart-unit').textContent=unit(metric);const range=$('#range').value;const cutoff=new Date();cutoff.setDate(cutoff.getDate()-Number(range));const r=rows().filter(e=>Number.isFinite(e[metric])&&(range==='all'||new Date(e.date+'T12:00:00')>=cutoff));if(!r.length){$('#chart').innerHTML='<div class="empty" style="min-height:225px"><strong>A fresh start, a bigger picture.</strong>Your progress chart will appear when you log a measurement.</div>';return;}const vals=r.map(e=>convert(e[metric],metric)),lo=Math.min(...vals)-.8,hi=Math.max(...vals)+.8,W=680,H=225,L=36,R=15,T=15,B=35;const dates=r.map(e=>new Date(e.date+'T12:00:00').getTime()),span=dates.at(-1)-dates[0];const x=i=>span?L+(dates[i]-dates[0])/span*(W-L-R):W/2,y=v=>T+(hi-v)/(hi-lo)*(H-T-B);const points=vals.map((v,i)=>`${x(i)},${y(v)}`).join(' ');$('#chart').innerHTML=`<svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${defs[metric]} chart showing ${r.length} check-ins, from ${vals[0].toFixed(1)} to ${vals.at(-1).toFixed(1)} ${unit(metric)}"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#dfe9d0" stop-opacity=".7"/><stop offset="100%" stop-color="#f8faf3" stop-opacity=".2"/></linearGradient></defs>${Array.from({length:5},(_,i)=>{const v=lo+(hi-lo)*i/4;return `<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#edf0e8" stroke-dasharray="3 5"/><text x="0" y="${y(v)+3}" font-family="sans-serif" font-size="10" fill="#a0a797">${v.toFixed(1)}</text>`;}).join('')}<polygon points="${x(0)},${H-B} ${points} ${x(r.length-1)},${H-B}" fill="url(#fade)"/><polyline points="${points}" fill="none" stroke="#6f8d53" stroke-width="2.5" stroke-linejoin="round"/>${vals.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="#fff" stroke="#6f8d53" stroke-width="2"><title>${dateLabel(r[i].date)}: ${v.toFixed(1)} ${unit(metric)}</title></circle>`).join('')}${[...new Set([0,Math.floor((r.length-1)/3),Math.floor((r.length-1)*2/3),r.length-1])].map(i=>`<text x="${x(i)}" y="${H-8}" text-anchor="${i===0?'start':i===r.length-1?'end':'middle'}" font-family="sans-serif" font-size="10" fill="#a0a797">${new Date(r[i].date+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'})}</text>`).join('')}</svg>`;}
function go(p){page=p;['overview','history','measurements'].forEach(s=>$('#'+s).hidden=s!==p);$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));}
function openEntry(id){if(demo&&id){toast('Sample entries are read-only. Start your journal to add your own.');return;}const e=state.entries.find(e=>e.id===id)||{};$('#entry-title').textContent=id?'Edit check-in':'Log measurements';$('#entry-id').value=e.id||'';$('#date').value=e.date||today();$('#date').max=today();const field=m=>`<label>${defs[m]} <span style="color:#909a86">(${unit(m)})</span><input type="number" id="f-${m}" step="0.1" min="0.1" max="${m==='weight'?1500:1000}" inputmode="decimal" placeholder="—" value="${e[m]!=null?num(e[m],m):''}"></label>`;$('#fields').innerHTML=['weight','waist'].map(field).join('');const extras=[...new Set([...state.extras,...Object.keys(defs).filter(m=>m!=='weight'&&m!=='waist'&&e[m]!=null)])];$('#extra-fields').innerHTML=extras.length?extras.map(field).join(''):'<p>Choose additional measurements in Settings.</p>';$('#note').value=e.note||'';$('#form-error').textContent='';$('#entry-dialog').showModal();}
$('#entry-form').addEventListener('submit',ev=>{ev.preventDefault();let e={id:$('#entry-id').value||crypto.randomUUID(),date:$('#date').value,note:$('#note').value.trim()};let count=0;Object.keys(defs).forEach(m=>{const input=$('#f-'+m);if(input&&input.value!==''){e[m]=canonical(Number(input.value),m);count++;}});if(!count){$('#form-error').textContent='Add at least one measurement to save your check-in.';return;}if(e.date>today()){ $('#form-error').textContent='Please choose today or an earlier date.';return;}state.entries=state.entries.filter(r=>r.id!==e.id);state.entries.push(e);state.started=true;demo=false;const ok=save();$('#entry-dialog').close();render();if(ok)toast('Check-in saved. A little step forward.');});
function settings(){ $('#units').value=state.units;$('#measurement-options').innerHTML=Object.keys(defs).filter(m=>!['weight','waist'].includes(m)).map(m=>`<label><input type="checkbox" value="${m}" ${state.extras.includes(m)?'checked':''}>${defs[m]}</label>`).join('');$('#demo-toggle').textContent=demo?'Leave sample journal':'Explore sample journal';$('#settings-dialog').showModal();}
$('#units').onchange=()=>{state.units=$('#units').value;save();render();};$('#measurement-options').onchange=()=>{state.extras=$$('#measurement-options input:checked').map(e=>e.value);save();render();};$('#demo-toggle').onclick=()=>{demo=!demo;if(!demo){state.started=true;save();}$('#settings-dialog').close();render();};$('#start').onclick=()=>openEntry();$('#add').onclick=()=>openEntry();$('#settings').onclick=settings;$('#manage').onclick=settings;$('#view-all').onclick=()=>go('history');$('#range').onchange=chart;$$('nav button').forEach(b=>b.onclick=()=>go(b.dataset.page));$$('.chart-tabs button').forEach(b=>b.onclick=()=>{metric=b.dataset.metric;$$('.chart-tabs button').forEach(t=>t.classList.toggle('active',t===b));chart();});$$('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.addEventListener('click',ev=>{const edit=ev.target.closest('[data-edit]'),del=ev.target.closest('[data-delete]');if(edit)openEntry(edit.dataset.edit);if(del){if(demo){toast('Sample entries are read-only.');return;}if(confirm('Delete this check-in? This cannot be undone.')){state.entries=state.entries.filter(e=>e.id!==del.dataset.delete);save();render();toast('Check-in deleted.');}}});$('#export').onclick=()=>{const data=rows();if(!data.length){toast('Add a check-in before exporting.');return;}const metrics=Object.keys(defs),csvCell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const safeNote=s=>/^[=+@\-\t\r]/.test(s||'')?"'"+s:s;const csv=[['Date',...metrics.map(m=>`${defs[m]} (${unit(m)})`),'Note'],...data.map(e=>[e.date,...metrics.map(m=>e[m]==null?'':num(e[m],m)),safeNote(e.note)])].map(r=>r.map(csvCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`weight-n-waist${demo?'-sample':''}-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};render();
